const giveUp = (reason: GiveUpReason): never => {
  quietly(() => o.onGiveUp?.({ attempts: attempt, reason, error })); // a throwing callback cannot replace `error`
  emit(o.onEvent, { type: "give-up", policy: o.name ?? "retry", attempts: attempt, reason, error });
  throw error; // the last error, unchanged
};

