for (let attempt = 1; ; attempt++) {
  signal?.throwIfAborted();
  try {
    const result = await operation(signal ?? NEVER);
    o.budget?.onSuccess();
    return result;
  } catch (error) {
    if (signal?.aborted) throw signal.reason;
    // shouldRetry -> budget.onFailure -> attempts -> canRetry -> backoff / Retry-After -> deadline
    quietly(() => o.onRetry?.({ attempt, delayMs, error })); // a throwing callback does not end the retries
    await sleep(delayMs, signal);
  }
}

