// solution (illustrative, NOT in the repo): src/decorrelated.ts
import type { Backoff } from "./backoff.js";

export interface DecorrelatedOptions { baseMs?: number; capMs?: number }

// Decorrelated jitter: sleep = min(cap, random_between(base, prev * 3)).
// STATELESS on purpose: one RetryPolicy (and its Backoff) is shared by every concurrent call,
// so a `prev` field would mix calls. We replay the chain from retry 1 to n with fresh draws.
export function decorrelatedJitter(options: DecorrelatedOptions = {}): Backoff {
  const base = options.baseMs ?? 100;
  const cap = options.capMs ?? 10_000;
  if (!Number.isFinite(base) || base < 0) throw new RangeError("baseMs must be >= 0");
  if (!Number.isFinite(cap) || cap < base) throw new RangeError("capMs must be >= baseMs");
  return {
    delayMs(retryNumber, random) {
      let prev = base;
      for (let i = 1; i <= retryNumber; i++) prev = Math.min(cap, base + random() * (prev * 3 - base));
      return Math.floor(prev);
    },
  };
}

