describe("decorrelatedJitter", () => {
  it("r = 0.5: 200, 350, 575, 912, then the cap", () => {
    const b = decorrelatedJitter({ baseMs: 100, capMs: 1000 });
    expect([1, 2, 3, 4, 5].map((n) => b.delayMs(n, () => 0.5))).toEqual([200, 350, 575, 912, 1000]);
  });

  it("stays in [base, cap] and is an integer for random draws", () => {
    const b = decorrelatedJitter({ baseMs: 50, capMs: 5000 });
    for (let n = 1; n <= 20; n++) for (let i = 0; i < 200; i++) {
      const d = b.delayMs(n, Math.random);
      expect(d).toBeGreaterThanOrEqual(50);
      expect(d).toBeLessThanOrEqual(5000);
      expect(Number.isInteger(d)).toBe(true);
    }
  });

  it("plugs into RetryPolicy (custom Backoff object)", async () => {
    const sleeps: number[] = [];
    let calls = 0;
    const policy = new RetryPolicy({
      backoff: decorrelatedJitter({ baseMs: 100, capMs: 1000 }),
      random: () => 0.5,
      sleep: async (ms) => void sleeps.push(ms),
    });
    expect(await policy.execute(async () => (++calls < 3 ? Promise.reject(new Error("x")) : "ok"))).toBe("ok");
    expect(sleeps).toEqual([200, 350]);
  });

  it.each([[{ baseMs: -1 }], [{ baseMs: 200, capMs: 100 }]])("rejects %j", (o) => {
    expect(() => decorrelatedJitter(o)).toThrow(RangeError);
  });
});

// solution (illustrative, NOT in the repo): src/pg-retry.ts
import { BrokenCircuitError, BulkheadRejectedError, TimeoutError } from "./errors.js";

const RETRYABLE_SQLSTATE = new Set(["40001", "40P01", "57P01", "53300"]);
const RETRYABLE_NET = new Set(["ECONNRESET", "ECONNREFUSED", "ETIMEDOUT", "EPIPE"]);
const AMBIGUOUS = new Set(["ECONNRESET", "EPIPE", "08006"]); // the query may have reached the server

export function isRetryablePg({ idempotent }: { idempotent: boolean }) {
  return (error: unknown): boolean => {
    if (error instanceof BrokenCircuitError || error instanceof BulkheadRejectedError) return false;
    if (error instanceof TimeoutError) return idempotent; // a write may have committed
    const code = (error as { code?: unknown } | null)?.code;
    if (typeof code !== "string") return false; // unknown: do not guess with a database
    if (!idempotent && AMBIGUOUS.has(code)) return false;
    return RETRYABLE_SQLSTATE.has(code) || RETRYABLE_NET.has(code) || code.startsWith("08");
  };
}

// test/pg-retry.test.ts
import { describe, expect, it } from "vitest";
import { TimeoutError } from "../src/errors.js";
import { isRetryablePg } from "../src/pg-retry.js";
import { RetryPolicy } from "../src/retry.js";

const pgError = (code: string) => Object.assign(new Error(`pg ${code}`), { code });

describe("isRetryablePg", () => {
  const read = isRetryablePg({ idempotent: true });
  const write = isRetryablePg({ idempotent: false });

  it.each([["40001", true], ["40P01", true], ["08006", true], ["53300", true], ["23505", false], ["42601", false]])(
    "idempotent: %s -> %s", (code, expected) => expect(read(pgError(code))).toBe(expected));

  it("timeouts and ambiguous connection losses are retried only when idempotent", () => {
    expect(read(new TimeoutError(100))).toBe(true);
    expect(write(new TimeoutError(100))).toBe(false);
    expect(write(pgError("ECONNRESET"))).toBe(false);
    expect(write(pgError("40001"))).toBe(true); // the server rolled it back: safe
  });

  it("with RetryPolicy: 40001 then success -> 2 calls; 23505 -> 1 call, not-retryable", async () => {
    const reasons: string[] = [];
    const policy = new RetryPolicy({ shouldRetry: write, sleep: async () => {}, onGiveUp: (e) => reasons.push(e.reason) });
    let calls = 0;
    expect(await policy.execute(async () => (++calls === 1 ? Promise.reject(pgError("40001")) : "ok"))).toBe("ok");
    expect(calls).toBe(2);
    calls = 0;
    await expect(policy.execute(async () => { calls++; throw pgError("23505"); })).rejects.toMatchObject({ code: "23505" });
    expect([calls, reasons]).toEqual([1, ["not-retryable"]]);
  });
});

