import { randomUUID } from "node:crypto";

export function chargeCard(input: ChargeInput, signal?: AbortSignal) {
  const key = randomUUID(); // NOT inside the arrow function: every attempt must reuse it
  return payments.execute(async (s) => {
    const res = await fetch(PAY_URL, {
      method: "POST", body: JSON.stringify(input), signal: s,
      headers: { "content-type": "application/json", "idempotency-key": key },
    });
    if (!res.ok) throw new HttpError(res.status, parseRetryAfter(res.headers.get("retry-after")));
    return res.json();
  }, signal);
}

